(function(){
'use strict';
if(typeof DATA==='undefined' || !Array.isArray(DATA) || typeof PUBLIC_DATA==='undefined') return;
const S=v=>(v==null?'':String(v));
const N=v=>S(v).toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ').trim();
const has=(v,x)=>N(v).includes(N(x));
const SAF='сафронова александра львовна';
const BOCH='бочковская анна викторовна';

// ПРАВКА №15, 01.09.2026.
// Прямое решение пользователя + форма Сафроновой 2026/27:
// кафедральные курсы А.Л. Сафроновой закрепляем в ауд.416.
// Общие/поточные курсы не переводим в 416: в её форме для них отдельно указана ауд.128.
function safDept(r){
  if(!r || N(r.teacher)!==SAF) return false;
  const d=N(r.discipline);
  if(d.includes('роль религи') || d.includes('восток и россия') || d.includes('страны азии и африки')) return false;
  return d.includes('южной азии') || d.includes('индийские княжества') || d==='нир студентов' ||
         (d.includes('спецсеминар по профилю подготовки') && N(r.group).includes('хинди'));
}
DATA.forEach(r=>{
  if(!safDept(r)) return;
  r.room_hint='416';
  r.quality=(S(r.quality)?S(r.quality)+' | ':'')+'01.09.2026, правка №15: по прямому решению ауд.416 закреплена за кафедральными занятиями А.Л. Сафроновой; её форма 2026/27 также прямо просит 416 для кафедральных курсов. День/время занятия не менялись.';
});

// 4 курс, историки-хинди: лекция Сафроновой остаётся Вт 10:40; меняется только аудитория 179 -> 416.
DATA.forEach(r=>{
  if(!r || N(r.teacher)!==SAF || S(r.course).trim()!=='4 бакалавриат') return;
  const d=N(r.discipline);
  if(d.includes('основные проблемы') && d.includes('южной азии') && (d.includes('лекц') || S(r.day).trim()==='Вт')){
    r.day='Вт'; r.time='10:40'; r.room_hint='416';
    r.quality='01.09.2026, правка №15: подтверждённый слот А.Л. Сафроновой Вт 10:40 сохранён; рабочая замена ауд.179 отменена, кафедральный курс возвращён в прямо запрошенную ауд.416. Другие занятия по времени не двигались.';
  }
});

// 3 курс, история религий Южной Азии: один совместный курс Сафронова + Бочковская,
// подтверждённый четверг 10:40. Аудиторию переводим в 416, время не меняем.
function isSouthReligion3(r){
  if(!r || S(r.course).trim()!=='3 бакалавриат') return false;
  const t=N(r.teacher), d=N(r.discipline);
  return (t===SAF || t===BOCH) && d.includes('история религий южной азии');
}
let southReligion=[];
for(let i=DATA.length-1;i>=0;i--){
  if(isSouthReligion3(DATA[i])){ southReligion.push(DATA[i]); DATA.splice(i,1); }
}
const rrReaders=['Сафронова Александра Львовна','Бочковская Анна Викторовна'];
rrReaders.forEach(t=>DATA.push({
  group:'3 курс, хинди — историки, политологи, филологи, экономисты',
  course:'3 бакалавриат',direction:'История + Политология + Филология + Экономика',
  day:'Чт',time:'10:40',discipline:'История религий Южной Азии',
  extra:'совместное чтение; один курс; преподаватели читают по распределению нагрузки',
  teacher:t,joint_readers:rrReaders.filter(x=>x!==t),room_hint:'416',
  quality:'01.09.2026, правка №15: прямой четверговый слот Чт 10:40 сохранён. Совместный курс А.Л. Сафроновой + А.В. Бочковской переведён в ауд.416 по решению закрепить 416 за кафедральными курсами Сафроновой. Это одна пара, не два одновременных занятия.'
}));

// У нефиксированных кафедральных курсов Сафроновой аудитория также закреплена заранее,
// но время по-прежнему не выдумываем.
DATA.forEach(r=>{
  if(!r || N(r.teacher)!==SAF) return;
  if((N(r.discipline).includes('социально-политическое развитие южной азии') || N(r.discipline)==='нир студентов') &&
     (N(r.day)==='уточняется' || N(r.time)==='уточняется')){
    r.room_hint='416';
    r.quality=(S(r.quality)?S(r.quality)+' | ':'')+'01.09.2026, правка №15: аудитория 416 закреплена; точное время остаётся «уточняется», поэтому новый временной конфликт не создаётся.';
  }
});

// Кириллина: пользователь просит заменить ауд.240 именно у занятия Вт 14:40.
// Сам слот и совместное чтение сохраняются. 228 не используем — там есть подтверждённое занятие Бойцова;
// 231 занят общим курсом «Восток и Россия»; 236 приоритетно закреплена за Тимониной;
// 179 занят Бочковской. Выбрана свободная ауд.167 (80 мест).
const kirReaders=['Кириллина Светлана Алексеевна','Жантиев Дмитрий Рустемович','Кобищанов Тарас Юрьевич','Орлов Владимир Викторович'];
function isKirHistory(r){
  if(!r || S(r.course).trim()!=='2 бакалавриат' || S(r.day).trim()!=='Вт' || S(r.time).trim()!=='14:40') return false;
  const d=N(r.discipline);
  return d==='история арабских стран' || d.includes('история изучаемой страны') && d.includes('история арабских стран');
}
let foundKir=false;
DATA.forEach(r=>{
  if(!isKirHistory(r)) return;
  foundKir=true;
  r.group='25Б/И202-арабский/3, 25Б/П202-арабский/3';
  r.direction='История + Политология';
  r.room_hint='167';
  r.extra='совместное чтение: С.А. Кириллина + Д.Р. Жантиев + Т.Ю. Кобищанов + В.В. Орлов; 2 ч/нед.';
  if(kirReaders.some(t=>N(t)===N(r.teacher))) r.joint_readers=kirReaders.filter(t=>N(t)!==N(r.teacher));
  r.quality='01.09.2026, правка №15: по прямому указанию аудитория занятия Вт 14:40 изменена 240 → 167. День, время, дисциплина, группы и состав совместного чтения не менялись. Ауд.167 выбрана после сверки утверждённых аудиторных правок: 228 занята Бойцовым, 231 — «Восток и Россия», 236 приоритетно закреплена за Тимониной, 179 — Бочковская; подтверждённого назначения 167 в Вт 14:40 нет.';
});
if(!foundKir){
  kirReaders.forEach(t=>DATA.push({
    group:'25Б/И202-арабский/3, 25Б/П202-арабский/3',course:'2 бакалавриат',direction:'История + Политология',
    day:'Вт',time:'14:40',discipline:'История арабских стран',
    extra:'совместное чтение: С.А. Кириллина + Д.Р. Жантиев + Т.Ю. Кобищанов + В.В. Орлов; 2 ч/нед.',
    teacher:t,joint_readers:kirReaders.filter(x=>x!==t),room_hint:'167',
    quality:'01.09.2026, правка №15: восстановлена текущая совместная запись Вт 14:40 и по прямому указанию аудитория изменена 240 → 167; время и состав курса сохранены.'
  }));
}

// Защита: фиксированную лекцию Кириллиной Вт 13:00, ауд.228 не трогаем.
DATA.forEach(r=>{
  if(N(r.teacher)==='кириллина светлана алексеевна' && S(r.day).trim()==='Вт' && S(r.time).trim()==='13:00' && N(r.discipline).includes('исламовед')) r.room_hint='228';
});

const rows=typeof isServiceRow==='function'?DATA.filter(r=>!isServiceRow(r)):DATA.slice();
PUBLIC_DATA.splice(0,PUBLIC_DATA.length,...rows);
try{if(typeof buildGroupItems==='function')buildGroupItems();}catch(e){}
try{if(typeof buildBrowseList==='function')buildBrowseList();}catch(e){}
try{if(typeof showEmpty==='function')showEmpty();}catch(e){}
})();
